Sensor sensor_create( UInt8 activation_count_trg , UInt32 timeout_trg , Boolean npc_trg , UInt8 activation_count_warn , UInt32 timeout_warn , Boolean npc_warn )
{
    Sensor sensor =(Sensor) vrtc_build( (Vrtc_Func)sensor_bypass_timeout , sizeof (struct s_Sensor ) );
	
	sensor->npc_trg  = npc_create( activation_count_trg  , timeout_trg );	
	sensor->npc_warn = npc_create( activation_count_warn , timeout_trg );
	
		
	sensor->status.is_disabled 	   = TRUE     ;	
	sensor->status.is_bypassed     = FALSE    ;									  	 
	sensor->status.npc_trg_enable  = npc_trg  ;	
	sensor->status.npc_warn_enable = npc_warn ;	
    
	
	return sensor ;            
}

